rows=[]
for raw in spec.strip().splitlines():
    fields=raw.strip().split('|')
    if len(fields)!=7: raise ValueError((len(fields),raw))
    ident,name,group,tech,exercise,challenge,feedback=fields
    rows.append(dict(id=ident,name=name,group=group,techniques=[x.strip() for x in tech.split(';')],starterExercise=exercise,advancedChallenge=challenge,feedbackQuestions=[x.strip() for x in feedback.split(';')],coachModes=['explore','learn','practice','critique','collaborate'],guidingPrinciple='You are the creator; B.E.N. provides questions, references, techniques and feedback, not a finished piece.'))
refs=[
  dict(name='The Metropolitan Museum of Art — Open Access',url='https://www.metmuseum.org/hubs/open-access',type='CC0 artwork reference',suitable=['painting','drawing','illustration','sculpture','ceramics','photography','textiles','fashion','printmaking'],note='Only objects explicitly marked Open Access/CC0; credit maker when possible.'),
  dict(name='Smithsonian Open Access',url='https://www.si.edu/openaccess',type='CC0 collections',suitable=['painting','sculpture','architecture','textiles','jewellery','craft-community','photography','floral'],note='Check individual item CC0 status, attribution and cultural context.'),
  dict(name='Purdue OWL',url='https://owl.purdue.edu/',type='writing education',suitable=['creative-writing','nonfiction','playwriting','screenwriting','poetry','spoken-word'],note='Link to guides; do not scrape or redistribute full content.'),
  dict(name='Wikimedia Commons',url='https://commons.wikimedia.org/',type='Mixed-license media archive',suitable=['photography','painting','drawing','architecture','graffiti','dance','theatre'],note='Check each file license and attribution before reuse.'),
  dict(name='Openverse',url='https://openverse.org/',type='Open-licensed image/audio discovery',suitable=['photography','painting','graphic-design','music-composition','sound-art','film'],note='Verify source-level license/credit; preview is for study.'),
  dict(name='Project Gutenberg',url='https://www.gutenberg.org/',type='Public-domain literary works',suitable=['creative-writing','poetry','nonfiction','playwriting','screenwriting'],note='Copyright status depends on jurisdiction; reference technique, not reproduction.'),
  dict(name='Europeana',url='https://www.europeana.eu/',type='Cultural collections with per-item rights',suitable=['painting','photography','film','fashion','dance','music-composition'],note='Rights and cultural context vary by item.'),
  dict(name='Internet Archive',url='https://archive.org/',type='Historical audio/video/text references',suitable=['film','music-composition','animation','theatre','dance','spoken-word'],note='Archive availability does not imply reuse permission.'),
]
output={'version':'2026-10-26','approach':'human-led creative learning, not default artwork generation','disciplines':rows,'references':refs,'curriculumStatus':'Original coaching scaffolds. External references are starting points, not proof of expert qualification or live search results.'}
(p/'config/creative-curriculum.json').write_text(json.dumps(output,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
print(f'Created {len(rows)} disciplines, {len(refs)} curated reference directories')
